insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O tribunal decidirá por maioria de votos. Em todos os julgamentos em matéria penal ou processual penal em órgãos colegiados, havendo empate, prevalecerá a decisão mais favorável ao indivíduo imputado, proclamando-se de imediato esse resultado, ainda que, nas hipóteses de vaga aberta a ser preenchida, de impedimento, de suspeição ou de ausência, tenha sido o julgamento tomado sem a totalidade dos membros. O acórdão será apresentado à conferência na primeira sessão seguinte à do julgamento, ou no prazo de duas sessões, pelo juiz incumbido de lavrá-lo.', '["Decisão por maioria de votos.","Empate: prevalece a decisão mais favorável ao imputado.","Acórdão apresentado na primeira sessão seguinte ou em duas sessões."]'::jsonb, '["Empate favorece o IMPUTADO (in dubio pro reo)."]'::jsonb, 'Julgamento empatado em habeas corpus: prevalece a decisão favorável ao paciente.', '["Assertiva que resolve o empate pelo voto de qualidade do presidente, contra o imputado, erra."]'::jsonb, '[]'::jsonb, '["Art. 616"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-615'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No julgamento das apelações poderá o tribunal, câmara ou turma proceder a novo interrogatório do acusado, reinquirir testemunhas ou determinar outras diligências.', '["Na apelação, o tribunal pode reinterrogar o acusado, reinquirir testemunhas ou determinar diligências."]'::jsonb, '["Poder instrutório do tribunal na apelação."]'::jsonb, 'O tribunal determina nova perícia ao julgar a apelação.', '["Assertiva que impede qualquer diligência instrutória pelo tribunal na apelação erra."]'::jsonb, '[]'::jsonb, '["Art. 617"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-616'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O tribunal, câmara ou turma atenderá nas suas decisões ao disposto nos arts. 383, 386 e 387, no que for aplicável, não podendo, porém, ser agravada a pena quando somente o réu houver apelado da sentença (proibição da reformatio in pejus).', '["Tribunal aplica os arts. 383, 386 e 387, no que couber.","Se só o réu apelou, a pena não pode ser agravada."]'::jsonb, '["Proibição de reformatio in pejus."]'::jsonb, 'Apenas o réu apela, e o tribunal não pode aumentar sua pena.', '["Assertiva que permite ao tribunal agravar a pena em apelação exclusiva da defesa erra."]'::jsonb, '[{"termo":"Reformatio in pejus","significado":"Piorar a situação do recorrente em seu próprio recurso."}]'::jsonb, '["Art. 383","Art. 386"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-617'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os regimentos dos Tribunais de Apelação estabelecerão as normas complementares para o processo e julgamento dos recursos e apelações.', '["Regimentos internos complementam o processo e julgamento dos recursos."]'::jsonb, '["Normas complementares regimentais."]'::jsonb, 'O regimento interno fixa detalhes da sessão de julgamento.', '["Assertiva que veda aos regimentos regular o processamento dos recursos erra."]'::jsonb, '[]'::jsonb, '["Art. 628"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-618'
