insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aos acórdãos proferidos pelos Tribunais de Apelação, câmaras ou turmas, poderão ser opostos embargos de declaração, no prazo de dois dias contados da sua publicação, quando houver na sentença ambiguidade, obscuridade, contradição ou omissão.', '["Embargos de declaração contra acórdão.","Prazo de dois dias da publicação.","Cabimento: ambiguidade, obscuridade, contradição ou omissão."]'::jsonb, '["Prazo de dois dias."]'::jsonb, 'A parte opõe embargos de declaração por omissão no acórdão em dois dias.', '["Assertiva que fixa em cinco dias o prazo dos embargos de declaração de acórdão erra: são dois dias."]'::jsonb, '[]'::jsonb, '["Art. 382"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-619'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os embargos de declaração serão deduzidos em requerimento de que constem os pontos em que o acórdão é ambíguo, obscuro, contraditório ou omisso. O requerimento será apresentado pelo relator e julgado, independentemente de revisão, na primeira sessão. Se não preenchidas as condições enumeradas neste artigo, o relator indeferirá desde logo o requerimento.', '["Requerimento indica os pontos ambíguos, obscuros, contraditórios ou omissos.","Julgado na primeira sessão, sem revisão.","Indeferimento liminar pelo relator se faltarem as condições."]'::jsonb, '["Julgados na primeira sessão."]'::jsonb, 'O relator indefere liminarmente embargos que não indicam o ponto omisso.', '["Assertiva que exige revisor no julgamento dos embargos de declaração erra."]'::jsonb, '[]'::jsonb, '["Art. 619"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-620'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A revisão dos processos findos será admitida quando a sentença condenatória for contrária ao texto expresso da lei penal ou à evidência dos autos; quando se fundar em depoimentos, exames ou documentos comprovadamente falsos; e quando, após a sentença, se descobrirem novas provas de inocência do condenado ou de circunstância que determine ou autorize diminuição especial da pena.', '["I: sentença contrária à lei penal ou à evidência dos autos.","II: sentença fundada em provas comprovadamente falsas.","III: novas provas de inocência ou de circunstância que diminua a pena."]'::jsonb, '["A revisão criminal só beneficia o condenado (pro reo)."]'::jsonb, 'Depois da condenação, surge prova nova de inocência: cabe revisão criminal.', '["Assertiva que admite revisão criminal em favor da acusação erra."]'::jsonb, '[{"termo":"Revisão criminal","significado":"Ação para rever condenação definitiva em favor do réu."}]'::jsonb, '["Art. 622"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-621'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A revisão poderá ser requerida em qualquer tempo, antes da extinção da pena ou após. Não será admissível a reiteração do pedido, salvo se fundado em novas provas.', '["Revisão a qualquer tempo, antes ou depois da extinção da pena.","Reiteração do pedido só com novas provas."]'::jsonb, '["Sem prazo decadencial."]'::jsonb, 'Mesmo extinta a pena, o condenado pode pedir revisão.', '["Assertiva que fixa prazo para a revisão criminal erra: pode ser requerida a qualquer tempo."]'::jsonb, '[]'::jsonb, '["Art. 621"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-622'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A revisão poderá ser pedida pelo próprio réu ou por procurador legalmente habilitado ou, no caso de morte do réu, pelo cônjuge, ascendente, descendente ou irmão.', '["Legitimados: o réu, procurador habilitado.","Morte do réu: cônjuge, ascendente, descendente ou irmão."]'::jsonb, '["Mesma ordem de sucessão do art. 31."]'::jsonb, 'Falecido o condenado, o cônjuge requer a revisão.', '["Assertiva que nega legitimidade aos familiares após a morte do condenado erra."]'::jsonb, '[]'::jsonb, '["Art. 31"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-623'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As revisões criminais serão processadas e julgadas pelo Supremo Tribunal Federal, quanto às condenações por ele proferidas, e pelo Tribunal Federal de Recursos, Tribunais de Justiça ou de Alçada nos demais casos. No STF e no Tribunal Federal de Recursos, o processo e julgamento obedecerão ao regimento interno. Nos Tribunais de Justiça ou de Alçada, o julgamento será efetuado pelas câmaras ou turmas criminais, reunidas em sessão conjunta, quando houver mais de uma, e, no caso contrário, pelo tribunal pleno. Onde houver quatro ou mais câmaras ou turmas, poderão ser constituídos dois ou mais grupos de câmaras para o julgamento da revisão.', '["STF julga revisão de suas condenações.","Tribunais de Justiça (e outros) nos demais casos.","Câmaras reunidas em sessão conjunta ou tribunal pleno.","Quatro ou mais câmaras: possíveis grupos de câmaras."]'::jsonb, '["A competência atual segue a Constituição (STJ, TRFs)."]'::jsonb, 'A revisão de condenação do Tribunal de Justiça é julgada pelas câmaras criminais reunidas.', '["Assertiva que atribui ao juiz de primeira instância o julgamento da revisão criminal erra."]'::jsonb, '[]'::jsonb, '["Art. 625"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-624'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O requerimento será distribuído a um relator e a um revisor, devendo funcionar como relator um desembargador que não tenha pronunciado decisão em qualquer fase do processo. O requerimento será instruído com a certidão de haver passado em julgado a sentença condenatória e com as peças necessárias à comprovação dos fatos arguidos. O relator poderá determinar que se apensem os autos originais, se daí não advier dificuldade à execução normal da sentença. Se o relator julgar insuficientemente instruído o pedido, indeferi-lo-á in limine, dando recurso para as câmaras reunidas ou para o tribunal. Interposto o recurso por petição, o relator apresentará o processo em mesa para o julgamento. Se o requerimento não for indeferido in limine, abrir-se-á vista ao procurador-geral, que dará parecer no prazo de dez dias; em seguida, relator e revisor examinarão os autos em igual prazo, e o pedido será julgado na sessão designada.', '["Relator e revisor; relator não pode ter decidido o caso antes.","Instrução com certidão do trânsito em julgado e peças.","Apensamento dos autos originais, se possível.","Indeferimento in limine, com recurso.","Parecer do procurador-geral em dez dias; relator e revisor em igual prazo."]'::jsonb, '["Relator imparcial: sem decisão prévia no processo."]'::jsonb, 'O requerimento de revisão vem com a certidão do trânsito em julgado.', '["Assertiva que permite ao desembargador que já decidiu o caso funcionar como relator da revisão erra."]'::jsonb, '[]'::jsonb, '["Art. 624"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-625'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Julgando procedente a revisão, o tribunal poderá alterar a classificação da infração, absolver o réu, modificar a pena ou anular o processo. De qualquer maneira, não poderá ser agravada a pena imposta pela decisão revista.', '["Revisão procedente: alterar a classificação, absolver, modificar a pena ou anular o processo.","Vedado agravar a pena."]'::jsonb, '["Proibição de agravamento da pena."]'::jsonb, 'O tribunal reduz a pena na revisão criminal.', '["Assertiva que permite agravar a pena na revisão criminal erra."]'::jsonb, '[]'::jsonb, '["Art. 621"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-626'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A absolvição implicará o restabelecimento de todos os direitos perdidos em virtude da condenação, devendo o tribunal, se for caso, impor a medida de segurança cabível.', '["Absolvição na revisão restabelece todos os direitos perdidos.","Tribunal pode impor a medida de segurança cabível."]'::jsonb, '["Efeito restituidor da absolvição."]'::jsonb, 'Revisão absolve o condenado, que recupera seus direitos.', '["Assertiva que mantém os efeitos da condenação após a absolvição na revisão erra."]'::jsonb, '[]'::jsonb, '["Art. 626"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-627'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

