insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'À vista da certidão do acórdão que cassar a sentença condenatória, o juiz mandará juntá-la imediatamente aos autos, para inteiro cumprimento da decisão.', '["Certidão do acórdão que cassar a condenação é juntada imediatamente aos autos.","Cumprimento integral da decisão."]'::jsonb, '["Cumprimento imediato."]'::jsonb, 'O juiz junta a certidão do acórdão e cumpre a decisão da revisão.', '["Assertiva que adia a juntada da certidão do acórdão erra: é imediata."]'::jsonb, '[]'::jsonb, '["Art. 626"]'::jsonb, 'under_review', 'claude'
