insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O tribunal, se o interessado o requerer, poderá reconhecer o direito a uma justa indenização pelos prejuízos sofridos. Por essa indenização, que será liquidada no juízo cível, responderá a União, se a condenação tiver sido proferida pela justiça do Distrito Federal ou de Território, ou o Estado, se o tiver sido pela respectiva justiça. A indenização não será devida se o erro ou a injustiça da condenação proceder de ato ou falta imputável ao próprio impetrante, como a confissão ou a ocultação de prova em seu poder, ou se a acusação houver sido meramente privada.', '["Indenização por erro judiciário, a requerimento.","Liquidação no juízo cível; responde a União ou o Estado.","Não é devida: culpa do próprio impetrante (confissão, ocultação de prova) ou acusação meramente privada."]'::jsonb, '["Indenização liquidada no cível."]'::jsonb, 'Absolvido na revisão, o interessado pede indenização, liquidada no juízo cível.', '["Assertiva que reconhece indenização mesmo quando o erro decorreu de confissão falsa do próprio condenado erra."]'::jsonb, '[]'::jsonb, '["Art. 626"]'::jsonb, 'under_review', 'claude'
