select u.id, u.content_sha256, 'Dar-se-á habeas corpus sempre que alguém sofrer ou se achar na iminência de sofrer violência ou coação ilegal na sua liberdade de ir e vir, salvo nos casos de punição disciplinar.', '["Habeas corpus contra violência ou coação ilegal à liberdade de locomoção.","Cabe também quando há iminência (habeas corpus preventivo).","Exceção: punição disciplinar (militar)."]'::jsonb, '["Habeas corpus preventivo (iminência) e liberatório (já preso).","A punição disciplinar militar: só quanto a ilegalidades formais (Constituição)."]'::jsonb, 'Pessoa ameaçada de prisão ilegal impetra habeas corpus preventivo.', '["Assertiva que restringe o habeas corpus a quem já está preso erra: cabe também na iminência de coação."]'::jsonb, '[{"termo":"Habeas corpus preventivo","significado":"Impetrado contra ameaça de coação ilegal."}]'::jsonb, '["Art. 648"]'::jsonb, 'under_review', 'claude'
