insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No âmbito de sua competência jurisdicional, qualquer autoridade judicial poderá expedir de ofício ordem de habeas corpus, individual ou coletivo, quando, no curso de qualquer processo judicial, verificar que, por violação ao ordenamento jurídico, alguém sofre ou se acha ameaçado de sofrer violência ou coação em sua liberdade de locomoção. A ordem de habeas corpus poderá ser concedida de ofício pelo juiz ou pelo tribunal em processo de competência originária ou recursal, ainda que não conhecidos a ação ou o recurso em que veiculado o pedido de cessação de coação ilegal.', '["Qualquer autoridade judicial pode expedir habeas corpus de ofício, individual ou coletivo.","Quando verificar, em qualquer processo, coação ilegal à liberdade.","Pode ser concedido mesmo sem conhecer a ação ou o recurso."]'::jsonb, '["Incluído pela Lei nº 14.836, de 2024.","Habeas corpus de ofício, individual ou coletivo."]'::jsonb, 'O tribunal, ao analisar um recurso, concede habeas corpus de ofício diante de coação ilegal.', '["Assertiva que condiciona o habeas corpus de ofício ao conhecimento do recurso erra: pode ser concedido ainda que a ação ou o recurso não seja conhecido."]'::jsonb, '[]'::jsonb, '["Art. 647"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-647-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A coação considerar-se-á ilegal quando não houver justa causa; quando alguém estiver preso por mais tempo do que determina a lei; quando quem ordenar a coação não tiver competência para fazê-lo; quando houver cessado o motivo que a autorizou; quando não for alguém admitido a prestar fiança, nos casos em que a lei a autoriza; quando o processo for manifestamente nulo; e quando extinta a punibilidade.', '["I: falta de justa causa.","II: prisão por mais tempo que o legal.","III: autoridade incompetente.","IV: cessou o motivo da coação.","V: negada fiança cabível.","VI: processo manifestamente nulo.","VII: punibilidade extinta."]'::jsonb, '["Rol de hipóteses de coação ilegal."]'::jsonb, 'Preso por mais tempo que a lei determina: coação ilegal.', '["Assertiva que exclui a extinção da punibilidade das hipóteses de coação ilegal erra."]'::jsonb, '[]'::jsonb, '["Art. 647"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-648'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

