insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete conhecer, originariamente, do pedido de habeas corpus ao Supremo Tribunal Federal, nos casos previstos na Constituição, e aos Tribunais de Apelação, sempre que os atos de violência ou coação forem atribuídos aos governadores ou interventores dos Estados ou Territórios e ao prefeito do Distrito Federal, ou a seus secretários, ou aos chefes de Polícia. A competência do juiz cessará sempre que a violência ou coação provier de autoridade judiciária de igual ou superior jurisdição. Não cabe habeas corpus contra a prisão administrativa, atual ou iminente, dos responsáveis por dinheiro ou valor pertencente à Fazenda Pública, alcançados ou omissos em fazer o seu recolhimento nos prazos legais, salvo se o pedido for acompanhado de prova de quitação ou de depósito, ou se a prisão exceder o prazo legal.', '["STF e Tribunais de Apelação têm competência originária.","Juiz não conhece de coação de autoridade judiciária de igual ou superior jurisdição.","Não cabe contra a prisão administrativa de responsáveis por dinheiro público, salvo exceções."]'::jsonb, '["Texto histórico: a competência atual está na Constituição.","A prisão administrativa foi extinta pela ordem constitucional atual."]'::jsonb, 'O habeas corpus contra ato de um tribunal é impetrado em tribunal superior.', '["Assertiva que permite ao juiz de primeira instância julgar habeas corpus contra ato de tribunal erra."]'::jsonb, '[]'::jsonb, '["Art. 647"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-650'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A concessão do habeas corpus não obstará, nem porá termo ao processo, desde que este não esteja em conflito com os fundamentos daquela.', '["Concessão do habeas corpus não encerra o processo.","Desde que o processo não conflite com os fundamentos da ordem."]'::jsonb, '["Não extingue, por si, a ação penal."]'::jsonb, 'A ordem concedida para soltar o réu não impede o prosseguimento do processo.', '["Assertiva que extingue o processo com a concessão do habeas corpus, em qualquer caso, erra."]'::jsonb, '[]'::jsonb, '["Art. 652"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-651'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se o habeas corpus for concedido em virtude de nulidade do processo, este será renovado.', '["Habeas corpus por nulidade do processo: o processo é renovado."]'::jsonb, '["Renovação dos atos nulos."]'::jsonb, 'Concedido o habeas corpus por nulidade, os atos viciados são refeitos.', '["Assertiva que arquiva o processo definitivamente após habeas corpus por nulidade erra: ele é renovado."]'::jsonb, '[]'::jsonb, '["Art. 573"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-652'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ordenada a soltura do paciente em virtude de habeas corpus, será condenada nas custas a autoridade que, por má-fé ou evidente abuso de poder, tiver determinado a coação. Neste caso, será remetida ao Ministério Público cópia das peças necessárias para ser promovida a responsabilidade da autoridade.', '["Autoridade que agiu com má-fé ou abuso de poder paga as custas.","Cópia das peças ao MP para apurar a responsabilidade."]'::jsonb, '["Responsabilização da autoridade coatora."]'::jsonb, 'Soltura por habeas corpus decorrente de abuso evidente: a autoridade paga as custas.', '["Assertiva que isenta a autoridade que agiu com abuso de poder das custas erra."]'::jsonb, '[]'::jsonb, '["Art. 654"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-653'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O habeas corpus poderá ser impetrado por qualquer pessoa, em seu favor ou de outrem, bem como pelo Ministério Público. A petição conterá o nome da pessoa que sofre ou está ameaçada de sofrer violência ou coação e o de quem exercer a violência, coação ou ameaça; a declaração da espécie de constrangimento ou, em caso de simples ameaça, as razões em que funda o seu temor; e a assinatura do impetrante, ou de alguém a seu rogo, e a designação das respectivas residências. Os juízes e os tribunais têm competência para expedir de ofício ordem de habeas corpus, quando no curso de processo verificarem que alguém sofre ou está na iminência de sofrer coação ilegal.', '["Impetrado por qualquer pessoa, em favor próprio ou alheio, ou pelo MP.","Petição: paciente, coator, espécie de constrangimento ou razões do temor, assinatura.","Habeas corpus de ofício por juízes e tribunais."]'::jsonb, '["Não exige advogado nem capacidade postulatória.","Impetrante e paciente podem ser pessoas diferentes."]'::jsonb, 'Qualquer pessoa pode impetrar habeas corpus em favor de um preso.', '["Assertiva que exige advogado para impetrar habeas corpus erra."]'::jsonb, '[{"termo":"Paciente","significado":"A pessoa que sofre ou ameaça sofrer a coação."}]'::jsonb, '["Art. 647-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-654'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O carcereiro ou o diretor da prisão, o escrivão, o oficial de justiça ou a autoridade judiciária ou policial que embaraçar ou procrastinar a expedição de ordem de habeas corpus, as informações sobre a causa da prisão, a condução e apresentação do paciente, ou a sua soltura, será multado, sem prejuízo da responsabilidade criminal.', '["Quem embaraça ou procrastina a expedição da ordem, informações, apresentação ou soltura é multado.","Alcança carcereiro, diretor, escrivão, oficial de justiça e autoridades."]'::jsonb, '["Sanção para quem retarda o habeas corpus."]'::jsonb, 'O diretor da prisão retarda a soltura determinada e é multado.', '["Assertiva que isenta o oficial de justiça de multa por procrastinar a ordem erra."]'::jsonb, '[]'::jsonb, '["Art. 656"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-655'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Recebida a petição de habeas corpus, o juiz, se julgar necessário, e estando preso o paciente, mandará que este lhe seja imediatamente apresentado em dia e hora que designar. Em caso de desobediência, será expedido mandado de prisão contra o detentor, que será processado na forma da lei, e o juiz providenciará para que o paciente seja tirado da prisão e apresentado em juízo.', '["Apresentação imediata do paciente preso, se necessária.","Desobediência: prisão do detentor.","Juiz providencia a retirada do paciente da prisão."]'::jsonb, '["Apresentação do paciente em juízo."]'::jsonb, 'O juiz determina que o preso seja apresentado em audiência.', '["Assertiva que dispensa a apresentação do paciente preso quando o juiz a julga necessária erra."]'::jsonb, '[]'::jsonb, '["Art. 657"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-656'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se o paciente estiver preso, nenhum motivo escusará a sua apresentação, salvo grave enfermidade do paciente; não estar ele sob a guarda da pessoa a quem se atribui a detenção; ou se o comparecimento não tiver sido determinado pelo juiz ou pelo tribunal. O juiz poderá ir ao local em que o paciente se encontrar, se este não puder ser apresentado por motivo de doença.', '["Regra: nenhum motivo escusa a apresentação do preso.","Exceções: grave enfermidade; paciente não está sob a guarda do detentor; comparecimento não determinado.","O juiz pode ir ao local, se o paciente estiver doente."]'::jsonb, '["Exceções restritas à apresentação."]'::jsonb, 'Paciente gravemente enfermo não é apresentado, e o juiz vai até ele.', '["Assertiva que escusa a apresentação por qualquer inconveniente erra."]'::jsonb, '[]'::jsonb, '["Art. 656"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-657'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O detentor declarará à ordem de quem o paciente estiver preso.', '["O detentor declara à ordem de quem o paciente está preso."]'::jsonb, '["Declaração do detentor."]'::jsonb, 'O diretor informa que o paciente está preso à ordem de determinado juiz.', '["Assertiva que dispensa a declaração do detentor sobre a ordem de prisão erra."]'::jsonb, '[]'::jsonb, '["Art. 656"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-658'
