insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se o juiz ou o tribunal verificar que já cessou a violência ou coação ilegal, julgará prejudicado o pedido.', '["Cessada a coação ilegal, o pedido é julgado prejudicado."]'::jsonb, '["Perda do objeto."]'::jsonb, 'O paciente já foi solto, e o habeas corpus é julgado prejudicado.', '["Assertiva que concede a ordem mesmo após a cessação da coação erra: o pedido fica prejudicado."]'::jsonb, '[]'::jsonb, '["Art. 660"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-659'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Efetuadas as diligências, e interrogado o paciente, o juiz decidirá, fundamentadamente, dentro de 24 horas. Se a decisão for favorável ao paciente, será logo posto em liberdade, salvo se por outro motivo dever ser mantido na prisão. Se os documentos que instruírem a petição evidenciarem a ilegalidade da coação, o juiz ou o tribunal ordenará que cesse imediatamente o constrangimento. Se a ilegalidade decorrer do fato de não ter sido o paciente admitido a prestar fiança, o juiz arbitrará o valor desta. Se a ordem for concedida para evitar ameaça de violência ou coação ilegal, dar-se-á ao paciente salvo-conduto assinado pelo juiz. Será incontinenti enviada cópia da decisão à autoridade que tiver ordenado a prisão.', '["Decisão fundamentada em 24 horas.","Decisão favorável: soltura imediata, salvo outra causa.","Ilegalidade evidente: cessa imediatamente o constrangimento.","Fiança negada ilegalmente: juiz arbitra o valor.","Habeas corpus preventivo: salvo-conduto.","Cópia da decisão à autoridade coatora."]'::jsonb, '["Salvo-conduto no habeas corpus preventivo.","Prazo de 24 horas."]'::jsonb, 'O juiz concede habeas corpus preventivo e entrega ao paciente um salvo-conduto.', '["Assertiva que fixa em 48 horas o prazo para o juiz decidir o habeas corpus erra: são 24 horas."]'::jsonb, '[{"termo":"Salvo-conduto","significado":"Documento que protege contra a prisão ilegal no habeas corpus preventivo."}]'::jsonb, '["Art. 647"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-660'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em caso de competência originária do Tribunal de Apelação, a petição de habeas corpus será apresentada ao secretário, que a enviará imediatamente ao presidente do tribunal, ou da câmara criminal, ou da turma, que estiver reunida, ou primeiro tiver de reunir-se.', '["Petição apresentada ao secretário do tribunal.","Enviada de imediato ao presidente do tribunal, da câmara ou da turma."]'::jsonb, '["Tramitação rápida na competência originária do tribunal."]'::jsonb, 'A petição vai imediatamente ao presidente da câmara criminal.', '["Assertiva que retarda o envio ao presidente para a próxima sessão ordinária erra."]'::jsonb, '[]'::jsonb, '["Art. 662"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-661'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se a petição contiver os requisitos do art. 654, §1º, o presidente, se necessário, requisitará da autoridade indicada como coatora informações por escrito. Faltando, porém, qualquer daqueles requisitos, o presidente mandará preenchê-lo, logo que lhe for apresentada a petição.', '["Petição regular: o presidente requisita informações da autoridade coatora, se necessário.","Faltando requisito: manda preenchê-lo."]'::jsonb, '["Informalismo: o vício é sanado, e não rejeitado de plano."]'::jsonb, 'Faltou indicar a residência do impetrante: o presidente manda completar.', '["Assertiva que rejeita a petição incompleta sem oportunidade de correção erra."]'::jsonb, '[]'::jsonb, '["Art. 654"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-662'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As diligências do artigo anterior não serão ordenadas, se o presidente entender que o habeas corpus deva ser indeferido in limine. Nesse caso, levará a petição ao tribunal, câmara ou turma, para que delibere a respeito.', '["Indeferimento liminar dispensa as diligências.","O presidente leva a petição ao órgão colegiado para deliberar."]'::jsonb, '["A decisão final cabe ao colegiado."]'::jsonb, 'O presidente entende ser caso de indeferimento liminar e leva a petição ao órgão colegiado.', '["Assertiva que permite ao presidente indeferir sozinho, sem levar a petição ao colegiado, erra, segundo a letra do art. 663."]'::jsonb, '[]'::jsonb, '["Art. 662"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-663'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Recebidas as informações, ou dispensadas, o habeas corpus será julgado na primeira sessão, podendo, entretanto, adiar-se o julgamento para a sessão seguinte. A decisão será tomada por maioria de votos. Havendo empate, se o presidente não tiver tomado parte na votação, proferirá voto de desempate; no caso contrário, prevalecerá a decisão mais favorável ao paciente.', '["Julgamento na primeira sessão, com adiamento possível para a seguinte.","Decisão por maioria.","Empate: voto de desempate do presidente se não votou; senão, a decisão mais favorável ao paciente."]'::jsonb, '["Empate favorece o paciente (art. 615, §1º)."]'::jsonb, 'O julgamento empata e prevalece a decisão mais favorável ao paciente.', '["Assertiva que resolve o empate contra o paciente erra."]'::jsonb, '[]'::jsonb, '["Art. 615"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-664'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O secretário do tribunal lavrará a ordem que, assinada pelo presidente do tribunal, câmara ou turma, será dirigida, por ofício ou telegrama, ao detentor, ao carcereiro ou autoridade que exercer ou ameaçar exercer o constrangimento. A ordem transmitida por telegrama obedecerá ao disposto no art. 289, parágrafo único, in fine.', '["Secretário lavra a ordem, assinada pelo presidente.","Dirigida por ofício ou telegrama ao detentor ou autoridade coatora."]'::jsonb, '["Hoje se usam meios eletrônicos."]'::jsonb, 'A ordem é enviada ao diretor do presídio para a soltura.', '["Assertiva que dispensa a assinatura do presidente na ordem de habeas corpus erra."]'::jsonb, '[]'::jsonb, '["Art. 289"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-665'
