select u.id, u.content_sha256, 'Os regimentos dos Tribunais de Apelação estabelecerão as normas complementares para o processo e julgamento do pedido de habeas corpus de sua competência originária.', '["Regimentos dos tribunais complementam o processo do habeas corpus de competência originária."]'::jsonb, '["Normas regimentais complementares."]'::jsonb, 'O regimento interno regula detalhes do julgamento do habeas corpus no tribunal.', '["Assertiva que veda ao regimento complementar o rito do habeas corpus erra."]'::jsonb, '[]'::jsonb, '["Art. 667"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-666'
