insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No processo e julgamento do habeas corpus de competência originária do Supremo Tribunal Federal, bem como nos de recurso das decisões de última ou única instância denegatórias de habeas corpus, observar-se-á, no que lhes for aplicável, o disposto nos artigos anteriores, devendo o regimento interno do tribunal estabelecer as normas complementares.', '["Habeas corpus originário do STF e recursos contra a denegação: aplicam-se, no que couber, as regras anteriores.","Regimento interno completa."]'::jsonb, '["Remissão ao rito geral."]'::jsonb, 'O STF aplica o rito geral do habeas corpus, complementado pelo regimento interno.', '["Assertiva que afasta as regras gerais do habeas corpus no STF erra."]'::jsonb, '[]'::jsonb, '["Art. 666"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-667'
