insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A execução, onde não houver juiz especial, incumbirá ao juiz da sentença, ou, se a decisão for do Tribunal do Júri, ao seu presidente. Se a decisão for de tribunal superior, nos casos de sua competência originária, caberá ao respectivo presidente prover-lhe a execução.', '["Execução cabe ao juiz da sentença (ou ao presidente do Júri), se não houver juiz especial.","Decisão de tribunal em competência originária: execução pelo respectivo presidente."]'::jsonb, '["Hoje a Lei de Execução Penal prevê o juízo da execução."]'::jsonb, 'Sem vara de execuções, o juiz da sentença executa a pena.', '["Assertiva que sempre atribui a execução ao Ministério Público erra."]'::jsonb, '[]'::jsonb, '["Art. 669"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-668'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Só depois de passar em julgado, será exequível a sentença, salvo quando condenatória, para o efeito de sujeitar o réu a prisão, ainda no caso de crime afiançável, enquanto não for prestada a fiança; e quando absolutória, para o fim de imediata soltura do réu, desde que não proferida em processo por crime a que a lei comine pena de reclusão, no máximo, por tempo igual ou superior a oito anos.', '["Regra: a sentença só é exequível após o trânsito em julgado.","Exceção condenatória: prisão enquanto não prestada a fiança.","Exceção absolutória: soltura imediata, salvo reclusão com máximo igual ou superior a oito anos."]'::jsonb, '["Dispositivo anterior ao art. 596, que determina a soltura imediata em qualquer absolvição."]'::jsonb, 'A sentença absolutória permite a soltura imediata do réu.', '["Assertiva que torna a sentença condenatória exequível antes do trânsito em julgado sempre erra."]'::jsonb, '[]'::jsonb, '["Art. 596"]'::jsonb, 'under_review', 'claude'
