insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No caso de decisão absolutória confirmada ou proferida em grau de apelação, incumbirá ao relator fazer expedir o alvará de soltura, de que dará imediatamente conhecimento ao juiz de primeira instância.', '["Absolvição confirmada ou proferida na apelação: o relator expede o alvará de soltura.","Comunica de imediato o juiz de primeira instância."]'::jsonb, '["O relator expede o alvará."]'::jsonb, 'O tribunal absolve o réu em apelação, e o relator expede o alvará de soltura.', '["Assertiva que atribui a expedição do alvará ao juiz de primeira instância apenas erra."]'::jsonb, '[]'::jsonb, '["Art. 596"]'::jsonb, 'under_review', 'claude'
