select u.id, u.content_sha256, 'Os incidentes da execução, como pedidos de progressão e livramento, serão resolvidos pelo respectivo juiz da execução.', '["Incidentes da execução são resolvidos pelo juiz da execução."]'::jsonb, '["Juízo da execução."]'::jsonb, 'O pedido de progressão de regime é decidido pelo juiz da execução.', '["Assertiva que remete os incidentes da execução ao tribunal erra."]'::jsonb, '[]'::jsonb, '["Art. 668"]'::jsonb, 'under_review', 'claude'
