select u.id, u.content_sha256, 'Computar-se-á na pena privativa da liberdade o tempo de prisão preventiva no Brasil ou no estrangeiro; de prisão provisória no Brasil ou no estrangeiro; e de internação em hospital ou manicômio.', '["Computa-se o tempo de prisão preventiva.","Prisão provisória.","Internação em hospital ou manicômio."]'::jsonb, '["Detração penal."]'::jsonb, 'Quem ficou preso preventivamente tem esse tempo descontado da pena.', '["Assertiva que não computa a prisão cumprida no estrangeiro erra."]'::jsonb, '[{"termo":"Detração","significado":"Desconto do tempo de prisão provisória da pena."}]'::jsonb, '["Art. 387, §2º"]'::jsonb, 'under_review', 'claude'
