insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Verificado que o réu, pendente a apelação por ele interposta, já sofreu prisão por tempo igual ao da pena a que foi condenado, o relator do feito mandará pô-lo imediatamente em liberdade, sem prejuízo do julgamento do recurso, salvo se, no caso de crime a que a lei comine pena de reclusão, no máximo, por tempo igual ou superior a oito anos, o tribunal entender conveniente a manutenção da prisão, nos termos do dispositivo.', '["Apelação do réu pendente e prisão já igual à pena imposta: liberdade imediata pelo relator.","O recurso segue em julgamento.","Exceção para reclusão de máximo igual ou superior a oito anos."]'::jsonb, '["Evita cumprimento da pena além do imposto."]'::jsonb, 'O réu já cumpriu a pena aplicada enquanto aguarda a apelação: o relator o solta.', '["Assertiva que mantém o réu preso após cumprir o tempo da pena aplicada, sem exceção, erra."]'::jsonb, '[]'::jsonb, '["Art. 672"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-673'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Transitando em julgado a sentença que impuser pena privativa de liberdade, se o réu já estiver preso, ou vier a ser preso, o juiz ordenará a expedição de carta de guia para o cumprimento da pena. Na hipótese do art. 82, última parte, a expedição da carta de guia será ordenada pelo juiz competente para a soma ou unificação das penas.', '["Trânsito em julgado: carta de guia para o cumprimento da pena.","Soma ou unificação das penas: carta de guia pelo juiz competente."]'::jsonb, '["Hoje se fala em guia de recolhimento (LEP)."]'::jsonb, 'Com o trânsito em julgado, o juiz expede a carta de guia.', '["Assertiva que dispensa a carta de guia para o início da pena erra."]'::jsonb, '[{"termo":"Carta de guia","significado":"Documento que autoriza o cumprimento da pena privativa de liberdade."}]'::jsonb, '["Art. 676"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-674'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No caso de ainda não ter sido expedido mandado de prisão, por tratar-se de infração penal em que o réu se livra solto ou por estar afiançado, o juiz, ou o presidente da câmara ou tribunal, se tiver havido recurso, fará expedir o mandado de prisão, logo que transite em julgado a sentença condenatória. Reformada pela superior instância a sentença absolutória, estando o réu solto, o presidente da câmara ou do tribunal fará, logo após a sessão de julgamento, remeter ao chefe de Polícia o mandado de prisão do condenado. Se o réu estiver em prisão especial, deverá ser expedida ordem para sua imediata remoção para prisão comum, até a expedição de carta de guia, ressalvada a legislação relativa aos militares.', '["Réu solto ou afiançado: mandado de prisão após o trânsito em julgado.","Reforma da absolvição: mandado remetido ao chefe de Polícia.","Prisão especial: remoção para a comum até a carta de guia."]'::jsonb, '["Dispositivo antecede as regras atuais da Lei de Execução Penal."]'::jsonb, 'Transitada em julgado a condenação, o juiz expede o mandado de prisão do réu solto.', '["Assertiva que dispensa mandado de prisão para o réu solto após o trânsito em julgado erra."]'::jsonb, '[]'::jsonb, '["Art. 674"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-675'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A carta de guia, extraída pelo escrivão e assinada pelo juiz, que a rubricará em todas as folhas, será remetida ao diretor do estabelecimento em que tenha de ser cumprida a sentença condenatória, e conterá o nome do réu e a alcunha por que for conhecido; a sua qualificação civil, instrução e, se constar, número do registro geral do Instituto de Identificação; e o teor integral da sentença condenatória e a data da terminação da pena. Expedida carta de guia para cumprimento de uma pena, se o réu estiver cumprindo outra, só depois de terminada a execução desta será aquela executada. Retificar-se-á a carta de guia sempre que sobrevenha modificação quanto ao início da execução ou ao tempo de duração da pena.', '["Carta de guia extraída pelo escrivão, assinada e rubricada pelo juiz.","Conteúdo: nome, alcunha, qualificação, teor da sentença e data de término.","Nova guia aguarda a conclusão da pena em curso.","Retificação sempre que mudar o início ou a duração."]'::jsonb, '["Conteúdo obrigatório da carta de guia."]'::jsonb, 'A carta de guia traz a qualificação do réu e o teor integral da sentença.', '["Assertiva que dispensa o teor integral da sentença na carta de guia erra."]'::jsonb, '[]'::jsonb, '["Art. 674"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-676'
