select u.id, u.content_sha256, 'Da carta de guia e seus aditamentos se remeterá cópia ao Conselho Penitenciário.', '["Cópia da carta de guia e aditamentos ao Conselho Penitenciário."]'::jsonb, '["Comunicação ao Conselho Penitenciário."]'::jsonb, 'O juiz remete cópia da carta de guia ao Conselho Penitenciário.', '["Assertiva que dispensa o envio ao Conselho Penitenciário erra."]'::jsonb, '[]'::jsonb, '["Art. 676"]'::jsonb, 'under_review', 'claude'
