insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As cartas de guia serão registradas em livro especial, segundo a ordem cronológica do recebimento, fazendo-se no curso da execução as anotações necessárias.', '["Registro em livro especial, por ordem cronológica.","Anotações durante a execução."]'::jsonb, '["Registro cronológico."]'::jsonb, 'As cartas de guia constam do livro especial, em ordem de recebimento.', '["Assertiva que dispensa o registro das cartas de guia erra."]'::jsonb, '[]'::jsonb, '["Art. 678"]'::jsonb, 'under_review', 'claude'
