select u.id, u.content_sha256, 'Computar-se-á no tempo da pena o período em que o condenado, por sentença irrecorrível, permanecer preso em estabelecimento diverso do destinado ao cumprimento dela.', '["O tempo preso em estabelecimento diverso do destinado à pena é computado."]'::jsonb, '["Computa-se o tempo, ainda que em local inadequado."]'::jsonb, 'O condenado aguarda vaga em delegacia, e esse tempo conta para a pena.', '["Assertiva que desconsidera o tempo preso em estabelecimento diverso erra."]'::jsonb, '[]'::jsonb, '["Art. 672"]'::jsonb, 'under_review', 'claude'
