insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se impostas cumulativamente penas privativas da liberdade, será executada primeiro a de reclusão, depois a de detenção e por último a de prisão simples.', '["Ordem de execução: reclusão, detenção e prisão simples."]'::jsonb, '["Primeiro a pena mais grave."]'::jsonb, 'Reclusão e detenção cumulativas: cumpre-se primeiro a reclusão.', '["Assertiva que inverte a ordem de execução, começando pela prisão simples, erra."]'::jsonb, '[]'::jsonb, '["Art. 676"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-681'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O sentenciado a que sobrevier doença mental, verificada por perícia médica, será internado em manicômio judiciário, ou, à falta, em outro estabelecimento adequado, onde lhe seja assegurada a custódia. Em caso de urgência, o diretor do estabelecimento penal poderá determinar a remoção do sentenciado, comunicando imediatamente ao juiz, que, em face da perícia médica, ratificará ou revogará a medida. Se a internação se prolongar até o término do prazo restante da pena e não houver sido imposta medida de segurança detentiva, o indivíduo terá o destino aconselhado pela sua enfermidade, feita a devida comunicação ao juiz de incapazes.', '["Doença mental superveniente na execução: internação em manicômio judiciário ou outro estabelecimento adequado.","Urgência: o diretor remove e comunica o juiz.","Fim do prazo restante da pena sem medida de segurança: destino aconselhado pela enfermidade."]'::jsonb, '["Hoje se aplica a Lei de Execução Penal (art. 183)."]'::jsonb, 'O condenado desenvolve doença mental e é internado em estabelecimento adequado.', '["Assertiva que mantém o sentenciado em doença mental no presídio comum erra."]'::jsonb, '[]'::jsonb, '["Art. 154"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-682'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O diretor da prisão a que o réu tiver sido recolhido provisoriamente ou em cumprimento de pena comunicará imediatamente ao juiz o óbito, a fuga ou a soltura do detido ou sentenciado para que fique constando dos autos. A certidão de óbito acompanhará a comunicação.', '["Diretor comunica imediatamente ao juiz óbito, fuga ou soltura.","Certidão de óbito acompanha a comunicação."]'::jsonb, '["Comunicação imediata."]'::jsonb, 'O diretor comunica a fuga do sentenciado ao juiz.', '["Assertiva que dispensa a comunicação da fuga ao juiz erra."]'::jsonb, '[]'::jsonb, '["Art. 684"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-683'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A recaptura do réu evadido não depende de prévia ordem judicial e poderá ser efetuada por qualquer pessoa.', '["Recaptura do evadido sem prévia ordem judicial.","Qualquer pessoa pode efetuá-la."]'::jsonb, '["Dispensa nova ordem."]'::jsonb, 'Qualquer pessoa pode recapturar o preso que fugiu.', '["Assertiva que exige nova ordem judicial para a recaptura do evadido erra."]'::jsonb, '[]'::jsonb, '["Art. 683"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-684'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Cumprida ou extinta a pena, o condenado será posto, imediatamente, em liberdade, mediante alvará do juiz, no qual se ressalvará a hipótese de dever o condenado continuar na prisão por outro motivo legal. Se tiver sido imposta medida de segurança detentiva, o condenado será removido para estabelecimento adequado.', '["Pena cumprida ou extinta: liberdade imediata por alvará.","Ressalva de outra causa legal de prisão.","Medida de segurança detentiva: remoção para estabelecimento adequado."]'::jsonb, '["Liberdade imediata."]'::jsonb, 'Cumprida a pena, o juiz expede o alvará de soltura.', '["Assertiva que mantém o condenado preso após o cumprimento da pena, sem outro motivo, erra."]'::jsonb, '[]'::jsonb, '["Art. 762"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-685'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A pena de multa será paga dentro de 10 dias após haver transitado em julgado a sentença que a impuser. Se interposto recurso da sentença, esse prazo será contado do dia em que o juiz ordenar o cumprimento da decisão da superior instância.', '["Multa paga em 10 dias do trânsito em julgado.","Com recurso: prazo conta da ordem de cumprimento da decisão superior."]'::jsonb, '["Hoje a multa é dívida de valor, cobrada conforme a Lei de Execução Penal."]'::jsonb, 'Transitada em julgado a sentença, o condenado paga a multa em 10 dias.', '["Assertiva que fixa em 30 dias o prazo para pagar a multa erra: são 10 dias."]'::jsonb, '[]'::jsonb, '["Art. 687"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-686'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz poderá, desde que o condenado o requeira, prorrogar o prazo do pagamento da multa até três meses, se as circunstâncias justificarem essa prorrogação; e permitir, nas mesmas circunstâncias, que o pagamento se faça em parcelas mensais, no prazo que fixar, mediante caução real ou fidejussória, quando necessário. O requerimento, em ambos os casos, será feito dentro do decêndio concedido para o pagamento da multa. A permissão para o pagamento em parcelas será revogada se o juiz verificar que o condenado dela se vale para fraudar a execução da pena, hipótese em que a caução se resolve em valor monetário.', '["Prorrogação do prazo em até três meses, a requerimento.","Pagamento em parcelas mensais, com caução, se necessário.","Requerimento em dez dias.","Revogação se houver fraude à execução."]'::jsonb, '["Prazo de requerimento: o decêndio (dez dias)."]'::jsonb, 'O condenado pede o parcelamento da multa dentro dos dez dias concedidos.', '["Assertiva que permite prorrogar o pagamento da multa por prazo indeterminado erra: é até três meses."]'::jsonb, '[]'::jsonb, '["Art. 686"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-687'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Findo o decêndio ou a prorrogação sem que o condenado efetue o pagamento, ou ocorrendo a hipótese do §2º do artigo anterior, observar-se-á o seguinte: possuindo o condenado bens sobre os quais possa recair a execução, será extraída certidão da sentença condenatória, a fim de que o Ministério Público proceda à cobrança judicial; sendo o condenado insolvente, far-se-á a cobrança mediante desconto de quarta parte de sua remuneração quando cumprir pena privativa de liberdade cumulativamente imposta com a de multa, mediante desconto em seu vencimento ou salário se, cumprida a pena privativa de liberdade ou concedido o livramento condicional, a multa não houver sido resgatada, ou mediante esse desconto se a multa for a única pena imposta ou no caso de suspensão condicional da pena. O desconto será feito mediante ordem ao empregador, à repartição competente ou à administração da entidade paraestatal, e o empregador será intimado sob pena de desobediência.', '["Não pago: com bens, certidão para cobrança judicial pelo MP.","Insolvente: desconto de quarta parte da remuneração (preso), desconto em vencimento ou salário (após a pena ou no livramento), ou na multa como pena única.","Desconto por ordem ao empregador, sob pena de desobediência."]'::jsonb, '["Regras anteriores à reforma (a multa é dívida de valor)."]'::jsonb, 'Multa não paga por condenado com bens: o MP promove a cobrança judicial.', '["Assertiva que prevê a prisão como primeira consequência do não pagamento da multa erra."]'::jsonb, '[]'::jsonb, '["Art. 687"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-688'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A multa será convertida, à razão de dez mil-réis por dia, em detenção ou prisão simples, no caso de crime ou de contravenção, se o condenado solvente frustrar o pagamento da multa ou se não forem pagas pelo condenado solvente as parcelas mensais autorizadas sem garantia. Se o juiz reconhecer desde logo a existência de causa para a conversão, a ela procederá de ofício ou a requerimento do Ministério Público, independentemente de audiência do condenado; caso contrário, depois de ouvir o condenado, poderá admitir a apresentação de prova pelas partes. O juiz, desde que transite em julgado a decisão, ordenará a expedição de mandado de prisão ou aditamento à carta de guia. Na hipótese do inciso II, a conversão será feita pelo valor das parcelas não pagas.', '["Conversão da multa em detenção ou prisão simples, se o solvente frustrar o pagamento.","Também se o solvente não pagar as parcelas autorizadas sem garantia.","Conversão de ofício ou a requerimento do MP.","Mandado de prisão ou aditamento à carta de guia."]'::jsonb, '["Conversão da multa em prisão foi eliminada pelo Código Penal reformado (a multa é dívida de valor).","Valor em moeda antiga."]'::jsonb, 'Texto histórico, sem aplicação prática atual.', '["Assertiva que admite a conversão da multa em prisão hoje erra, à luz do Código Penal reformado."]'::jsonb, '[]'::jsonb, '["Art. 690"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-689'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz tornará sem efeito a conversão, expedindo alvará de soltura ou cassando a ordem de prisão, se o condenado, em qualquer tempo, pagar a multa ou prestar caução real ou fidejussória que lhe assegure o pagamento. No caso da caução, antes de homologada, será ouvido o Ministério Público dentro do prazo de dois dias.', '["Conversão sem efeito se o condenado pagar a multa ou prestar caução.","Em qualquer tempo.","Caução: oitiva do MP em dois dias antes da homologação."]'::jsonb, '["Prazo de dois dias para o MP."]'::jsonb, 'Pagando a multa, o condenado tem a conversão cassada.', '["Assertiva que impede a revogação da conversão após certo prazo erra: é em qualquer tempo."]'::jsonb, '[]'::jsonb, '["Art. 689"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-690'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz dará à autoridade administrativa competente conhecimento da sentença transitada em julgado que impuser ou de que resultar a perda da função pública ou a incapacidade temporária para investidura em função pública ou para exercício de profissão ou atividade.', '["Comunicação à autoridade administrativa da sentença que impuser perda de função pública ou incapacidade temporária."]'::jsonb, '["Efeito da condenação."]'::jsonb, 'O juiz comunica ao órgão público a perda do cargo decorrente da condenação.', '["Assertiva que dispensa a comunicação à autoridade administrativa erra."]'::jsonb, '[]'::jsonb, '["Art. 92 do Código Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-691'
