insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No caso de incapacidade temporária ou permanente para o exercício do pátrio poder, da tutela ou da curatela, o juiz providenciará para que sejam acautelados, no juízo competente, a pessoa e os bens do menor ou do interdito.', '["Incapacidade para o poder familiar, tutela ou curatela: o juiz providencia a proteção da pessoa e dos bens do menor ou interdito."]'::jsonb, '["Proteção do incapaz."]'::jsonb, 'O condenado perde o poder familiar, e o juiz providencia a proteção do filho.', '["Assertiva que dispensa providências quanto aos bens do menor ou interdito erra."]'::jsonb, '[]'::jsonb, '["Art. 693"]'::jsonb, 'under_review', 'claude'
