insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A incapacidade permanente ou temporária para o exercício da autoridade marital ou do pátrio poder será averbada no registro civil.', '["Incapacidade para a autoridade marital ou o pátrio poder é averbada no registro civil."]'::jsonb, '["Averbação no registro civil."]'::jsonb, 'A perda do poder familiar é averbada no registro civil.', '["Assertiva que dispensa a averbação no registro civil erra."]'::jsonb, '[]'::jsonb, '["Art. 692"]'::jsonb, 'under_review', 'claude'
