insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As penas acessórias consistentes em interdições de direitos serão comunicadas ao Instituto de Identificação e Estatística ou estabelecimento congênere, figurarão na folha de antecedentes do condenado e serão mencionadas no rol de culpados.', '["Interdições de direitos são comunicadas ao Instituto de Identificação.","Constam da folha de antecedentes e do rol de culpados."]'::jsonb, '["Efeitos registrais."]'::jsonb, 'A interdição é anotada na folha de antecedentes do condenado.', '["Assertiva que dispensa a menção das interdições na folha de antecedentes erra."]'::jsonb, '[]'::jsonb, '["Art. 695"]'::jsonb, 'under_review', 'claude'
