insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Iniciada a execução das interdições temporárias, o juiz, de ofício, a requerimento do Ministério Público ou do condenado, fixará o seu termo final, completando as providências determinadas nos artigos anteriores.', '["Iniciada a interdição temporária, o juiz fixa o termo final.","De ofício ou a requerimento do MP ou do condenado."]'::jsonb, '["Fixação do termo final da interdição."]'::jsonb, 'O juiz fixa a data final da interdição temporária de direitos.', '["Assertiva que deixa a interdição temporária sem termo final erra."]'::jsonb, '[]'::jsonb, '["Art. 694"]'::jsonb, 'under_review', 'claude'
